/**
 * CareerPulse AI - Recommendation Model
 * Persists grounded career recommendations generated by LLM AI (Groq / Gemini) or the deterministic rule-based engine.
 */

import mongoose from 'mongoose';

const RecommendationSchema = new mongoose.Schema(
  {
    user: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: true,
      index: true
    },
    type: {
      type: String,
      required: true,
      enum: ['quiz-group', 'diploma', 'career-12th'],
      index: true
    },
    sourceRef: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'QuizAttempt',
      default: null
    },
    input: {
      type: mongoose.Schema.Types.Mixed,
      default: {}
    },
    results: [
      {
        id: {
          type: String,
          required: true
        },
        name: {
          type: String,
          required: true
        },
        category: {
          type: String,
          required: true,
          enum: ['best', 'stretch', 'safe']
        },
        reason: {
          type: String,
          required: true
        },
        matchScore: {
          type: Number,
          required: true,
          min: 0,
          max: 100
        },
        type: {
          type: String,
          enum: ['course', 'college'],
          default: 'college'
        },
        collegeId: {
          type: String,
          default: ''
        },
        courseId: {
          type: String,
          default: ''
        },
        prevCutoff: {
          type: Number,
          default: null
        },
        cutoffType: {
          type: String,
          default: ''
        },
        academicYear: {
          type: String,
          default: ''
        },
        chanceLabel: {
          type: String,
          default: ''
        },
        chanceVariant: {
          type: String,
          default: 'slate'
        },
        district: {
          type: String,
          default: ''
        },
        isOtherDistrict: {
          type: Boolean,
          default: false
        }
      }
    ],
    summary: {
      type: String,
      default: ''
    },
    districtNote: {
      type: String,
      default: null
    },
    lowCutoffMessage: {
      type: String,
      default: null
    },
    generatedBy: {
      type: String,
      required: true,
      enum: ['groq', 'gemini', 'fallback', 'grok'],
      default: 'fallback'
    },
    fallbackReason: {
      type: String,
      default: null
    }
  },
  {
    timestamps: true
  }
);

RecommendationSchema.index({ user: 1, type: 1, createdAt: -1 });

export const Recommendation = mongoose.model('Recommendation', RecommendationSchema);
export default Recommendation;
